POST /api/method/frappe.desk.query_repor.body:
{"message":{"script":"// Copyright (c) 2015, Frappe Technologies Pvt. Ltd. and Contributors
// License: GNU General Public License v3. See license.txt

frappe.query_reports["Accounts Payable"] = {
	filters: [
		{
			fieldname: "company",
			label: __("Company"),
			fieldtype: "Link",
			options: "Company",
			reqd: 1,
			default: frappe.defaults.get_user_default("Company"),
		},
		{
			fieldname: "report_date",
			label: __("Report Date"),
			fieldtype: "Date",
			default: frappe.datetime.get_today(),
		},
		{
			fieldname: "finance_book",
			label: __("Finance Book"),
			fieldtype: "Link",
			options: "Finance Book",
		},
		{
			fieldname: "cost_center",
			label: __("Cost Center"),
			fieldtype: "MultiSelectList",
			get_data: function (txt) {
				return frappe.db.get_link_options("Cost Center", txt, {
					company: frappe.query_report.get_filter_value("company"),
				});
			},
			options: "Cost Center",
		},
		{
			fieldname: "project",
			label: __("Project"),
			fieldtype: "MultiSelectList",
			options: "Project",
			get_data: function (txt) {
				return frappe.db.get_link_options("Project", txt, {
					company: frappe.query_report.get_filter_value("company"),
				});
			},
		},
		{
			fieldname: "party_account",
			label: __("Payable Account"),
			fieldtype: "Link",
			options: "Account",
			get_query: () => {
				var company = frappe.query_report.get_filter_value("company");
				return {
					filters: {
						company: company,
						account_type: "Payable",
						is_group: 0,
					},
				};
			},
		},
		{
			fieldname: "ageing_based_on",
			label: __("Ageing Based On"),
			fieldtype: "Select",
			options: "Posting Date\nDue Date\nSupplier Invoice Date",
			default: "Due Date",
		},
		{
			fieldname: "age_as_on",
			label: __("Age as on"),
			fieldtype: "Select",
			options: "Report Date\nToday",
			default: "Report Date",
		},
		{
			fieldname: "range",
			label: __("Ageing Range"),
			fieldtype: "Data",
			default: "30, 60, 90, 120",
		},
		{
			fieldname: "payment_terms_template",
			label: __("Payment Terms Template"),
			fieldtype: "Link",
			options: "Payment Terms Template",
		},
		{
			fieldname: "party_type",
			label: __("Party Type"),
			fieldtype: "Autocomplete",
			options: get_party_type_options(),
			on_change: function () {
				frappe.query_report.set_filter_value("party", "");
				let is_supplier = frappe.query_report.get_filter_value("party_type") === "Supplier";
				let supplier_group_filter = frappe.query_report.get_filter("supplier_group");
				if (supplier_group_filter) {
					supplier_group_filter.df.hidden = !is_supplier;
				}
				frappe.query_report.toggle_filter_display("supplier_group", !is_supplier);
				if (!is_supplier) {
					frappe.query_report.set_filter_value("supplier_group", []);
				}
			},
		},
		{
			fieldname: "party",
			label: __("Party"),
			fieldtype: "MultiSelectList",
			options: "party_type",
			get_data: function (txt) {
				if (!frappe.query_report.filters) return;

				let party_type = frappe.query_report.get_filter_value("party_type");
				if (!party_type) return;

				return frappe.db.get_link_options(party_type, txt);
			},
		},
		{
			fieldname: "supplier_group",
			label: __("Supplier Group"),
			fieldtype: "MultiSelectList",
			options: "Supplier Group",
			get_data: function (txt) {
				return frappe.db.get_link_options("Supplier Group", txt);
			},
			hidden: 1,
		},
		{
			fieldname: "group_by_party",
			label: __("Group By Supplier"),
			fieldtype: "Check",
		},
		{
			fieldname: "based_on_payment_terms",
			label: __("Based On Payment Terms"),
			fieldtype: "Check",
		},
		{
			fieldname: "show_remarks",
			label: __("Show Remarks"),
			fieldtype: "Check",
		},
		{
			fieldname: "show_future_payments",
			label: __("Show Future Payments"),
			fieldtype: "Check",
		},
		{
			fieldname: "for_revaluation_journals",
			label: __("Revaluation Journals"),
			fieldtype: "Check",
		},
		{
			fieldname: "ignore_accounts",
			label: __("Group by Voucher"),
			fieldtype: "Check",
		},
		{
			fieldname: "in_party_currency",
			label: __("In Party Currency"),
			fieldtype: "Check",
		},
		{
			fieldname: "handle_employee_advances",
			label: __("Handle Employee Advances"),
			fieldtype: "Check",
		},
	],

	formatter: function (value, row, column, data, default_formatter) {
		value = default_formatter(value, row, column, data);
		if (data && data.bold) {
			value = value.bold();
		}
		return value;
	},

	onload: function (report) {
		report.page.add_inner_button(__("Accounts Payable Summary"), function () {
			var filters = report.get_values();
			frappe.set_route("query-report", "Accounts Payable Summary", { company: filters.company });
		});

		if (frappe.boot.sysdefaults.default_ageing_range) {
			report.set_filter_value("range", frappe.boot.sysdefaults.default_ageing_range);
		}
	},
};

erpnext.utils.add_dimensions("Accounts Payable", 10);

function get_party_type_options() {
	let options = [];
	frappe.db
		.get_list("Party Type", { filters: { account_type: "Payable" }, fields: ["name"] })
		.then((res) => {
			res.forEach((party_type) => {
				options.push(party_type.name);
			});
		});
	return options;
}


//# sourceURL=accounts_payable.js","html_format":"<style>
	.print-format {
		padding: 4mm;
		font-size: 8.0pt !important;
	}
	.print-format td {
		vertical-align:middle !important;
	}
	</style>

	<h2 class="text-center" style="margin-top:0">{%= __(report.report_name) %}</h2>
	<h4 class="text-center">
		{% if (filters.party) { %}
			{%= __(filters.party) %}
		{% } %}
	</h4>
	<h6 class="text-center">
			{% if (filters.tax_id) { %}
			{%= __("Tax Id: ")%}	{%= filters.tax_id %}
			{% } %}
	</h6>
	<h5 class="text-center">
		{%= __(filters.ageing_based_on) %}
		{%= __("Until") %}
		{%= frappe.datetime.str_to_user(filters.report_date) %}
	</h5>

	<div class="clearfix">
		<div class="pull-left">
		{% if(filters.payment_terms) { %}
			<strong>{%= __("Payment Terms") %}:</strong> {%= filters.payment_terms %}
		{% } %}
		</div>
		<div class="pull-right">
		{% if(filters.credit_limit) { %}
			<strong>{%= __("Credit Limit") %}:</strong> {%= format_currency(filters.credit_limit) %}
		{% } %}
		</div>
	</div>

	{% if(filters.show_future_payments) { %}
		{% var balance_row = data.slice(-1).pop();
			var start = report.columns.findIndex((elem) => (elem.fieldname == 'age'));
			var range1 = report.columns[start].label;
			var range2 = report.columns[start+1].label;
			var range3 = report.columns[start+2].label;
			var range4 = report.columns[start+3].label;
			var range5 = report.columns[start+4].label;
			var range6 = report.columns[start+5].label;
		%}
		{% if(balance_row) { %}
		<table class="table table-bordered table-condensed">
			<caption class="text-right">(Amount in {%= data[0]["currency"] || "" %})</caption>
				<colgroup>
					<col style="width: 30mm;">
					<col style="width: 18mm;">
					<col style="width: 18mm;">
					<col style="width: 18mm;">
					<col style="width: 18mm;">
					<col style="width: 18mm;">
					<col style="width: 18mm;">
					<col style="width: 18mm;">
				</colgroup>

			<thead>
				<tr>
					<th>{%= __(" ") %}</th>
					<th>{%= __(range1) %}</th>
					<th>{%= __(range2) %}</th>
					<th>{%= __(range3) %}</th>
					<th>{%= __(range4) %}</th>
					<th>{%= __(range5) %}</th>
					<th>{%= __(range6) %}</th>
					<th>{%= __("Total") %}</th>
				</tr>
			</thead>
			<tbody>
				<tr>
					<td>{%= __("Total Outstanding") %}</td>
					<td class="text-right">
						{%= format_number(balance_row["age"], null, 2) %}
					</td>
					<td class="text-right">
						{%= format_currency(balance_row["range1"], data[data.length-1]["currency"]) %}
					</td>
					<td class="text-right">
						{%= format_currency(balance_row["range2"], data[data.length-1]["currency"]) %}
					</td>
					<td class="text-right">
						{%= format_currency(balance_row["range3"], data[data.length-1]["currency"]) %}
					</td>
					<td class="text-right">
						{%= format_currency(balance_row["range4"], data[data.length-1]["currency"]) %}
					</td>
					<td class="text-right">
						{%= format_currency(balance_row["range5"], data[data.length-1]["currency"]) %}
					</td>
					<td class="text-right">
						{%= format_currency(flt(balance_row["outstanding"]), data[data.length-1]["currency"]) %}
					</td>
				</tr>
					<td>{%= __("Future Payments") %}</td>
					<td></td>
					<td></td>
					<td></td>
					<td></td>
					<td></td>
					<td></td>
					<td class="text-right">
						{%= format_currency(flt(balance_row[("future_amount")]), data[data.length-1]["currency"]) %}
					</td>
				<tr class="cvs-footer">
					<th class="text-left">{%= __("Cheques Required") %}</th>
					<th></th>
					<th></th>
					<th></th>
					<th></th>
					<th></th>
					<th></th>
					<th class="text-right">
						{%= format_currency(flt(balance_row["outstanding"] - balance_row[("future_amount")]), data[data.length-1]["currency"]) %}</th>
				</tr>
			</tbody>

		</table>
		{% } %}
	{% } %}
	<table class="table table-bordered">
		<thead>
			<tr>
				{% if(report.report_name === "Accounts Receivable" || report.report_name === "Accounts Payable") { %}
					<th style="width: 10%">{%= __("Date") %}</th>
					<th style="width: 4%">{%= __("Age (Days)") %}</th>

					{% if(report.report_name === "Accounts Receivable" && filters.show_sales_person) { %}
						<th style="width: 14%">{%= __("Reference") %}</th>
						<th style="width: 10%">{%= __("Sales Person") %}</th>
					{% } else { %}
						<th style="width: 24%">{%= __("Reference") %}</th>
					{% } %}
					{% if(!filters.show_future_payments) { %}
						<th style="width: 20%">{%= (filters.party) ? __("Remarks"): __("Party") %}</th>
					{% } %}
					<th style="width: 10%; text-align: right">{%= __("Invoiced Amount") %}</th>
					{% if(!filters.show_future_payments) { %}
						<th style="width: 10%; text-align: right">{%= __("Paid Amount") %}</th>
						<th style="width: 10%; text-align: right">{%= report.report_name === "Accounts Receivable" ? __('Credit Note') : __('Debit Note') %}</th>
					{% } %}
					<th style="width: 10%; text-align: right">{%= __("Outstanding Amount") %}</th>
					{% if(filters.show_future_payments) { %}
						{% if(report.report_name === "Accounts Receivable") { %}
							<th style="width: 12%">{%= __("Customer LPO No.") %}</th>
						{% } %}
						<th style="width: 10%">{%= __("Future Payment Ref") %}</th>
						<th style="width: 10%">{%= __("Future Payment Amount") %}</th>
						<th style="width: 10%">{%= __("Remaining Balance") %}</th>
					{% } %}
				{% } else { %}
					<th style="width: 40%">{%= (filters.party) ? __("Remarks"): __("Party") %}</th>
					<th style="width: 15%">{%= __("Total Invoiced Amount") %}</th>
					<th style="width: 15%">{%= __("Total Paid Amount") %}</th>
					<th style="width: 15%">{%= report.report_name === "Accounts Receivable Summary" ? __('Credit Note Amount') : __('Debit Note Amount') %}</th>
					<th style="width: 15%">{%= __("Total Outstanding Amount") %}</th>
				{% } %}
			</tr>
		</thead>
		<div class="show-filters">
			{% if subtitle %}
				{{ subtitle }}
				<hr>
			{% endif %}
		</div>
		<tbody>
			{% for(var i=0, l=data.length; i<l; i++) { %}
				<tr>
				{% if(report.report_name === "Accounts Receivable" || report.report_name === "Accounts Payable") { %}
					{% if(data[i]["party"]) { %}
						<td>{%= frappe.datetime.str_to_user(data[i]["posting_date"]) %}</td>
						<td style="text-align: right">{%= data[i]["age"] %}</td>
						<td>
							{% if(!filters.show_future_payments) { %}
								{%= data[i]["voucher_type"] %}
								<br>
							{% } %}
							{%= data[i]["voucher_no"] %}
						</td>

						{% if(report.report_name === "Accounts Receivable" && filters.show_sales_person) { %}
						<td>{%= data[i]["sales_person"] %}</td>
						{% } %}

						{% if(!filters.show_future_payments) { %}
						<td>
							{% if(!filters.party?.length) { %}
								{%= data[i]["party"] %}
								{% if(data[i]["customer_name"] && data[i]["customer_name"] != data[i]["party"]) { %}
									<br> {%= data[i]["customer_name"] %}
								{% } else if(data[i]["supplier_name"] != data[i]["party"]) { %}
									<br> {%= data[i]["supplier_name"] %}
								{% } %}
							{% } %}
							<div>
							{% if data[i]["remarks"] %}
								{%= __("Remarks") %}:
								{%= data[i]["remarks"] %}
							{% } %}
							</div>
						</td>
						{% } %}

						<td style="text-align: right">
							{%= format_currency(data[i]["invoiced"], data[i]["currency"]) %}</td>

						{% if(!filters.show_future_payments) { %}
							<td style="text-align: right">
								{%= format_currency(data[i]["paid"], data[i]["currency"]) %}</td>
							<td style="text-align: right">
								{%= format_currency(data[i]["credit_note"], data[i]["currency"]) %}</td>
						{% } %}
						<td style="text-align: right">
							{%= format_currency(data[i]["outstanding"], data[i]["currency"]) %}</td>

						{% if(filters.show_future_payments) { %}
							{% if(report.report_name === "Accounts Receivable") { %}
								<td style="text-align: right">
									{%= data[i]["po_no"] %}</td>
							{% } %}
							<td style="text-align: right">{%= data[i]["future_ref"] %}</td>
							<td style="text-align: right">{%= format_currency(data[i]["future_amount"], data[i]["currency"]) %}</td>
							<td style="text-align: right">{%= format_currency(data[i]["remaining_balance"], data[i]["currency"]) %}</td>
						{% } %}
					{% } else { %}
						<td></td>
						{% if(!filters.show_future_payments) { %}
						<td></td>
						{% } %}
						{% if(report.report_name === "Accounts Receivable" && filters.show_sales_person) { %}
						<td></td>
						{% } %}
						<td></td>
						<td style="text-align: right"><b>{%= __("Total") %}</b></td>
						<td style="text-align: right">
							{%= format_currency(data[i]["invoiced"], data[i]["currency"] ) %}</td>

						{% if(!filters.show_future_payments) { %}
							<td style="text-align: right">
